<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Можно ли оплатить командировку с лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если командировка связана с исполнением сопровождаемого контракта. Выплаты работникам перечисляются на их банковские счета, билеты и гостиницы можно оплатить поставщикам напрямую, а оплаченные своими деньгами расходы — возместить."}}, {"@type": "Question", "name": "Можно ли снять наличные на командировку с лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Система казначейских платежей безналичная, кассовое обеспечение для коммерческих участников казначейского сопровождения не предусмотрено. Аванс перечисляется сотруднику на карту."}}, {"@type": "Question", "name": "Каким кодом платить командировочные сотруднику?", "acceptedAnswer": {"@type": "Answer", "text": "Выплаты работникам, занятым в исполнении контракта, идут по группе кодов 0100 «Выплаты персоналу»; детализированный подкод сверяйте с действующей редакцией Приложения 3 к приказу № 214н и требованиями вашего ТОФК."}}, {"@type": "Question", "name": "Можно ли оплатить билеты и гостиницу напрямую с лицевого счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Авиационные и железнодорожные билеты, гостиничные услуги и перевозки входят в перечень исключений подпункта 4 пункта 3 статьи 242.23 БК — их оплачивают контрагентам на обычные банковские счета."}}, {"@type": "Question", "name": "Какие суточные не облагаются НДФЛ в 2026 году?", "acceptedAnswer": {"@type": "Answer", "text": "700 ₽ за каждый день командировки по России и 2500 ₽ — за границей (ст. 217 НК). Те же лимиты действуют для страховых взносов (ст. 422 НК). Превышение — облагаемый доход работника."}}, {"@type": "Question", "name": "Можно ли установить суточные выше лимита?", "acceptedAnswer": {"@type": "Answer", "text": "Да, размер суточных определяет работодатель локальным актом. С превышения удерживается НДФЛ и начисляются взносы, а для целевых средств сумма должна соответствовать расчёту цены контракта и раздельному учёту."}}, {"@type": "Question", "name": "Что делать при срочной командировке?", "acceptedAnswer": {"@type": "Answer", "text": "Оплатить поездку собственными средствами, а затем возместить расходы с лицевого счёта кодом с первым разрядом 9 — при условии о возмещении в контракте и с копиями платёжных документов."}}, {"@type": "Question", "name": "Нужен ли авансовый отчёт?", "acceptedAnswer": {"@type": "Answer", "text": "Да, общие правила сохраняются: отчёт в три рабочих дня после возвращения, подтверждающие документы, возврат неизрасходованного остатка. Для возмещения с лицевого счёта авансовый отчёт — часть комплекта."}}, {"@type": "Question", "name": "Почему казначейство может вернуть распоряжение на командировочные?", "acceptedAnswer": {"@type": "Answer", "text": "Типовые причины: цель командировки не связана с контрактом, неверный код направления расходования, выплата не помещается в Сведения об операциях, нет документов-оснований или ИГК в назначении платежа."}}, {"@type": "Question", "name": "Как оплачивают командировки по гособоронзаказу?", "acceptedAnswer": {"@type": "Answer", "text": "Режим отдельного счёта в уполномоченном банке жёстче: платежи вне закрытого перечня разрешённых проводят в пределах месячного лимита «иных расходов» либо из собственных средств с отнесением на себестоимость."}}, {"@type": "Question", "name": "Учитываются ли командировочные в раздельном учёте?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Командировочные по контракту — прямые расходы на его исполнение либо распределяемые накладные; они отражаются в раздельном учёте и должны биться с выплатами с лицевого счёта."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как оплатить командировку по сопровождаемому контракту", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Проверьте целевую связь", "text": "Цель командировки должна быть прямо связана с исполнением сопровождаемого контракта и так сформулирована в приказе."}, {"@type": "HowToStep", "position": 2, "name": "Выберите маршрут оплаты", "text": "Выплата сотруднику с лицевого счёта, прямая оплата билетов и гостиниц поставщику или возмещение собственных расходов."}, {"@type": "HowToStep", "position": 3, "name": "Сверьте Сведения об операциях", "text": "По нужному коду направления расходования должен быть показатель и достаточный остаток; при необходимости уточните Сведения заранее."}, {"@type": "HowToStep", "position": 4, "name": "Подготовьте документы-основания", "text": "Приказ и расчёт — для выплаты работнику; договор и счёт — для прямой оплаты; авансовый отчёт и копии платёжек — для возмещения."}, {"@type": "HowToStep", "position": 5, "name": "Сформируйте распоряжение", "text": "Код направления расходования, ИГК и назначение платежа со ссылкой на документ-основание."}, {"@type": "HowToStep", "position": 6, "name": "Пройдите санкционирование", "text": "Проверка территориальным органом казначейства по порядку приказа № 214н — по общему правилу не позднее двух рабочих дней."}, {"@type": "HowToStep", "position": 7, "name": "Закройте командировку", "text": "Авансовый отчёт в три рабочих дня, возврат неизрасходованного остатка, отражение расходов в раздельном учёте по контракту."}]}
